      "id": "criterion-2",
      "status": "satisfied",
      "evidence": "Focused app tests and the full npm test workflow passed; source ownership, FIFO advancement, duplicate-event idempotence, and no terminal-click restart are asserted."
    }
  ],
  "changedFiles": [
    "tests/test_app.mjs"
  ],
  "testsAddedOrUpdated": [
