		const fifth = new Blob(["fifth"]);
		loaded.audioQueue.push(fourth, fifth);
		loaded.playNext();
		const staleReject = player.playPromises[5].reject;
		loaded.playNext();
		assert.equal(urls.get(player.src), fifth);
